              <CardContent className="space-y-6 px-4 md:px-6">
                {formData.cloudDownloads.map((cloud, ci) => (
                  <div key={ci} className="border border-[#2d1b54] rounded-xl p-4 space-y-4 bg-[#1a103c]/30">
