                            <Button type="button" onClick={() => removeDownloadLink(ci, li)} variant="outline" size="sm" className="bg-[#1a103c] border-[#2d1b54] text-red-400 h-8 w-8 p-0"><Trash2 className="h-3 w-3" /></Button>
