              <CardContent className="px-4 md:px-6">
                <Input type="date" value={formData.releaseDate} onChange={e => setFormData({ ...formData, releaseDate: e.target.value })} className="bg-[#1a103c] border-[#2d1b54] text-white text-sm" />
