            {/* Submit */}
            <div className="sticky bottom-0 bg-[#090514]/95 backdrop-blur-md border-t border-[#2d1b54] p-4 -mx-4 flex gap-3">
              <Button type="submit" className="flex-1 bg-[#9d4edd] hover:bg-[#7b2cbf] text-white font-bold py-3 text-base">
