                    <Input id="publisher" placeholder="e.g. Electronic Arts, Ubisoft..." value={formData.publisher || ""} onChange={e => setFormData({ ...formData, publisher: e.target.value })} className="bg-[#1a103c] border-[#2d1b54] text-white text-sm" />
