                        <Button type="button" onClick={() => addDownloadLink(ci)} variant="outline" size="sm" className="bg-[#1a103c] border-[#2d1b54] text-white text-xs"><Plus className="h-3 w-3 mr-1" />Add Link</Button>
                      </div>
