                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <Label htmlFor="title" className="text-white text-sm">Title *</Label>
                    <Input id="title" value={formData.title} onChange={e => {
                      setFormData({ ...formData, title: e.target.value })
