                } text-xs sm:text-sm px-2 sm:px-3 py-1 sm:py-2 flex-shrink-0`}
            >
              <span className="hidden xs:inline">{tab.label}</span>
              <span className="xs:hidden">{tab.label.split(' ')[0]}</span>
              <span className="ml-1">({count})</span>
