        {globalSearch && ` (filtered from ${items.length} total)`}
      </div>

      <div className="grid grid-cols-1 gap-3 md:gap-4">
        {paginatedItems.map((item) => (
          <Card key={item.id} className="bg-gray-700 border-gray-600">
