          setTimeout(() => {
            const el = document.getElementById('pending-review-section')
            if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' })
          }, 100)
        }
      }).catch(() => { })
    showReviewToast()
  }

  const scrollToPendingReview = () => {
    setTimeout(() => {
      const el = document.getElementById('pending-review-section')
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' })
    }, 100)
  }

  const submitReport = async () => {
