                <div className="absolute bottom-0 left-0 right-0 p-2 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                  <p className="text-white text-[10px] font-medium line-clamp-2">{g.title}</p>
                </div>
              </div>
