                  <div>
                    <p className="text-white text-sm font-semibold">{user?.name}</p>
                    <div className="flex gap-0.5 mt-0.5">
                      {[1, 2, 3, 4, 5].map(s => <Star key={s} className={`w-3 h-3 ${s <= myReview.rating ? 'text-yellow-500 fill-yellow-500' : 'text-gray-600'}`} />)}
                    </div>
