                  if (!confirm('Delete this review and submit a new one?') ) return
                  await fetch(`/api/reviews?id=${myReview.id}`, { method: 'DELETE' })
                  setMyReview(null)
                }}>
                Delete & Write New Review
              </Button>
            </div>
          </div>
        </div>
