                          <div>
                            <div className="flex items-center gap-2 flex-wrap">
                              <span className="text-white font-semibold text-[15px]">{r.user_name}</span>
                              <span className="text-[#4a3d6b] text-sm">{formatDate(r.created_at)}</span>
