                  if (!confirm('Are you sure you want to withdraw your review?')) return
                  await fetch(`/api/reviews?id=${myReview.id}`, { method: 'DELETE' })
                  setMyReview(null)
                  setToast({ msg: 'Your review has been withdrawn', type: 'info' })
                  setTimeout(() => setToast(null), 4000)
                }}>
                Withdraw Review
