                  style={{ background: "rgba(157,78,221,0.15)", border: "1px solid rgba(157,78,221,0.4)", color: "#c77dff" }}>
                  <Building2 className="w-3.5 h-3.5" />
                  {(game as any).publisher}
                  <ExternalLink className="w-3 h-3 opacity-60" />
                </Link>
