            {game.size && (
              <div>
                <div className="flex items-center gap-2 text-purple-700 dark:text-purple-400 text-xs font-bold uppercase tracking-widest mb-1.5">
                  <HardDrive className="w-4 h-4" />File Size
                </div>
                <p className="text-white text-sm font-medium">{game.size}</p>
              </div>
            )}
            {game.releaseDate && (
              <div>
                <div className="flex items-center gap-2 text-purple-700 dark:text-purple-400 text-xs font-bold uppercase tracking-widest mb-1.5">
                  <Calendar className="w-4 h-4" />Released
                </div>
                <p className="text-white text-sm font-medium">{new Date(game.releaseDate).getFullYear()}</p>
              </div>
            )}
            <div>
              <div className="flex items-center gap-2 text-purple-700 dark:text-purple-400 text-xs font-bold uppercase tracking-widest mb-1.5">
                <Clock className="w-4 h-4" />
                {game.updatedDate && game.updatedDate !== game.uploadDate ? 'Updated' : 'Published'}
              </div>
              <p className="text-white text-sm font-medium">
                {game.updatedDate && game.updatedDate !== game.uploadDate
                  ? formatDate(game.updatedDate)
                  : formatDate(game.publishedDate || game.uploadDate)}
