                  </h2>
                  <div className="flex gap-3 overflow-x-auto pb-2 scrollbar-hide">
                    {topInCategory.map((g, i) => <GameCard key={g.id} g={g} index={i} />)}
                  </div>
                </div>
              )}
            </div>
          )
        })()
