                        onClick={() => setShowReviewModal(true)}
                        className="mt-3 px-5 py-2 rounded-xl bg-[#9d4edd] hover:bg-[#7b2cbf] text-white text-sm font-semibold transition-all"
                      >
                        Write a Review
                      </button>
                    </div>
                  )}
                </div>

