        {/* Game Cover */}
        <div className="relative w-full lg:w-72 flex-shrink-0">
          <div className="relative aspect-[3/4] rounded-xl overflow-hidden shadow-2xl">
            <img
              src={game.image || "/placeholder.svg"}
