                  style={{ background: "rgba(157,78,221,0.15)", border: "1px solid rgba(157,78,221,0.4)", color: "#c77dff" }}>
                  <Building2 className="w-3.5 h-3.5" />
                  {(game as any).publisher}
                  <ExternalLink className="w-3 h-3 opacity-60" />
                </Link>
              </div>
            )}
            {game.size && (
              <div>
                <div className="flex items-center gap-2 text-purple-700 dark:text-purple-400 text-xs font-bold uppercase tracking-widest mb-1.5">
                  <HardDrive className="w-4 h-4" />File Size
                </div>
                <p className="text-white text-sm font-medium">{game.size}</p>
              </div>
            )}
            {game.releaseDate && (
              <div>
                <div className="flex items-center gap-2 text-purple-700 dark:text-purple-400 text-xs font-bold uppercase tracking-widest mb-1.5">
                  <Calendar className="w-4 h-4" />Released
                </div>
                <p className="text-white text-sm font-medium">{new Date(game.releaseDate).getFullYear()}</p>
              </div>
            )}
            <div>
              <div className="flex items-center gap-2 text-purple-700 dark:text-purple-400 text-xs font-bold uppercase tracking-widest mb-1.5">
                <Clock className="w-4 h-4" />
                {game.updatedDate && game.updatedDate !== game.uploadDate ? 'Updated' : 'Published'}
              </div>
              <p className="text-white text-sm font-medium">
                {game.updatedDate && game.updatedDate !== game.uploadDate
                  ? formatDate(game.updatedDate)
                  : formatDate(game.publishedDate || game.uploadDate)}
              </p>
            </div>
          </div>

          {/* Uploader */}
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-2">
              <User className="w-4 h-4 text-purple-600 dark:text-purple-400" />
              <p className="text-gray-600 dark:text-gray-400 text-xs font-medium">Uploaded by</p>
            </div>
            {(game.uploaderName || game.uploader) ? (
              <Link href={`/profile`} className="flex items-center gap-2 text-purple-700 dark:text-purple-400 hover:text-purple-500 text-sm font-bold transition-colors">
                {game.uploaderName || game.uploader}
              </Link>
            ) : (
              <div className="flex items-center gap-2">
                <span className="text-purple-700 dark:text-purple-400 text-sm font-bold">BullzGamez Team</span>
                <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-purple-600 text-white text-[10px] font-bold uppercase tracking-wider">
                  Admin
                </span>
              </div>
            )}
