              Download Now
            </button>
            {(trailerYtId || game.trailerUrl) && (
              <Button variant="outline" className="border-border text-foreground hover:bg-accent hover:text-accent-foreground" onClick={() => setTrailerOpen(true)}>
                <Play className="w-4 h-4 mr-2" />
                Trailer
              </Button>
