    width: 100%;
    height: 100%;
    margin: 0;
    padding: 0;
  }

  body {
    @apply bg-background text-foreground;
    width: 100%;
    min-height: 100%;
    margin: 0;
    padding: 0;
    overflow-x: hidden;
  }
}

/* Random Game Wheel Spin Animation */
@keyframes wheelSpin {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

@keyframes wheelSpinFast {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(1080deg);
  }
}

@keyframes pulseGlow {
  0%, 100% {
    box-shadow: 0 0 20px rgba(157,78,221,0.4), 0 0 40px rgba(157,78,221,0.2);
  }
  50% {
    box-shadow: 0 0 30px rgba(157,78,221,0.8), 0 0 60px rgba(157,78,221,0.4);
  }
}

@keyframes particleOrbit {
  0% {
    transform: rotate(0deg) translateX(30px) rotate(0deg);
  }
  100% {
    transform: rotate(360deg) translateX(30px) rotate(-360deg);
  }
}

@keyframes rainbowPulse {
  0%, 100% {
    filter: brightness(1) saturate(1);
  }
  50% {
    filter: brightness(1.3) saturate(1.5);
  }
}

@keyframes diceRoll {
  0% {
    transform: rotateX(0deg) rotateY(0deg) rotateZ(0deg);
  }
  16% {
    transform: rotateX(180deg) rotateY(90deg) rotateZ(0deg);
  }
  33% {
    transform: rotateX(360deg) rotateY(180deg) rotateZ(90deg);
  }
  50% {
    transform: rotateX(540deg) rotateY(270deg) rotateZ(180deg);
  }
  66% {
    transform: rotateX(720deg) rotateY(360deg) rotateZ(270deg);
  }
  83% {
    transform: rotateX(900deg) rotateY(450deg) rotateZ(360deg);
  }
  100% {
    transform: rotateX(1080deg) rotateY(540deg) rotateZ(450deg);
  }
}

.dice-cube {
  animation-timing-function: cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.dice-face {
  backface-visibility: visible;
}


/* Hero carousel animations */
@keyframes heroFadeIn {
  from {
    opacity: 0;
    transform: translateX(40px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes heroSlideUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.hero-text-anim {
  animation: heroFadeIn 0.6s ease-out forwards;
}

.hero-slide-up {
  animation: heroSlideUp 0.5s ease-out forwards;
}

/* Smooth horizontal scrolling containers */
.scroll-container {
  scrollbar-width: thin;
  scrollbar-color: #2d1b54 transparent;
}

.scroll-container::-webkit-scrollbar {
  height: 6px;
}

.scroll-container::-webkit-scrollbar-track {
  background: transparent;
}

.scroll-container::-webkit-scrollbar-thumb {
  background: #2d1b54;
  border-radius: 3px;
}

.scroll-container::-webkit-scrollbar-thumb:hover {
  background: #9d4edd;
}

/* Game card hover effects */
.game-card-hover {
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.game-card-hover:hover {
  transform: translateY(-6px) scale(1.03);
  box-shadow: 0 12px 40px rgba(0, 188, 212, 0.15);
}

/* Full width sections */
.full-width {
  width: 100vw;
  max-width: 100vw;
  margin-left: calc(-50vw + 50%);
  margin-right: calc(-50vw + 50%);
}

/* Fix for horizontal scrollbar */
html,
body {
  overflow-x: hidden;
  width: 100%;
}

/* Remove default margins */
body {
  margin: 0;
  padding: 0;
}

/* Ensure full height */
html,
body,
#__next {
  min-height: 100vh;
}

/* ====== LIGHT MODE OVERRIDES ====== */
/* When .dark class is removed, switch all hardcoded dark bg/text */
html:not(.dark) {
  --background: #f0f0f5;
  --foreground: #1a1a2e;
