                <span className="ml-3 text-sm font-bold px-3 py-1.5 rounded-lg align-middle inline-flex items-center gap-1.5 text-white" style={{ background: "linear-gradient(135deg, rgba(88,28,135,0.5), rgba(126,34,158,0.4))", border: "1px solid rgba(126,34,158,0.6)", boxShadow: "0 0 15px rgba(124,58,237,0.5)", animation: "flashOn 1.5s ease-in-out 3, glowOn 0.5s ease-in-out 1.5s forwards" }}>
                  <Sparkles className="w-3.5 h-3.5 text-purple-200" style={{ animation: "flashOn 1.5s ease-in-out 3" }} />
