    setReportDone(true)
    setTimeout(() => { setShowReportModal(false); setReportDone(false); setReportDesc("") }, 2000)
  }

  if (!game) return null

  const formatDate = (dateStr?: string) => {
    if (!dateStr) return "Unknown"
    try {
