  const token = userCtx?.token

  const isPCGame = game?.category === "PC Games"
  const isAndroid = game?.category === "Android Games"

  const averageRating = typeof game?.rating === 'number' ? game.rating : parseFloat(String(game?.rating || '4.5'))
