      setIsLoaded(true)
    } else {
      setIsLoaded(true)
    }
  }, [game?.reviews])

// Load approved reviews + user's pending review (fallback/fresh data)
  useEffect(() => {
    if (!game?.id) return
    fetch(`/api/reviews?game_id=${game.id}`)
      .then(r => r.json()).then(d => {
        if (d.reviews) {
