                            <div className="bg-[#0d0820]/60 border border-[#2d1b54]/30 rounded-lg p-5">
                              <p className="text-[#c4b5de] text-[15px] leading-relaxed italic"><RichContent text={spotlightReview.content} /></p>
                            </div>
                          )}
